import logging

from taf.ul.bts_kpi_report_generator.converter.ReleaseFileCreator import ReleaseFileCreator
from taf.ul.bts_kpi_report_generator.generator.GenerateFiles import GenerateFiles
from taf.ul.bts_kpi_report_generator.generator.GenerateJSON import GenerateJSON
from taf.ul.bts_kpi_report_generator.generator.SheetCreator import SheetCreator
from taf.ul.bts_kpi_report_generator.parser.FilesParser import FilesParser
from taf.ul.bts_kpi_report_generator.parser.ReadSourceKPI import ReadSourceKPI
from taf.ul.bts_kpi_report_generator.parser.ScanCounters import ScanCounters


class bts_kpi_report_generator:
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    @staticmethod
    def convert_xml_yaml(path_xml):
        """
        Method to convert XML with NIDD to YAML
        :param path_xml: path to XML file with NIDD
        """
        logging.debug('Convert XML to YAML')
        release_file_creator = ReleaseFileCreator(path_xml)
        release_file_creator.create_release_file()

    @staticmethod
    def generate_kpi_report(path_dir, source_kpi, kpi_to_generate='all', kpi_type=None, build='NA', generate_html_xlsx=False,
                            generate_json=False, number_of_start_intervals_to_skip=0, number_of_end_intervals_to_skip=0, report_name='KPI_Report'):
        """
        Method to generate KPI report and optional file XLSX, HTML with counter and JSOn file with results KPI
        :param path_dir: str - path catalog with files: PM, HASH, XML
        :param source_kpi: str or dict - source path file with KPIs release
        :param kpi_to_generate: str or dict - list needed KPI, can be given as  path to YAML or dict {'KPI': target}, default is 'all', result all KPI
        :param kpi_type:
        :param build: str - version build, default 'NA'
        :param generate_html_xlsx: bool - generate HTML and XLSX files with counters, default False
        :param generate_json: bool - generate JSON files with results, default False
        :param number_of_start_intervals_to_skip: int - start skip measurement, default 0
        :param number_of_end_intervals_to_skip: int - end skip measurement, default 0
        :param report_name: str - name for file XLSX with report, default 'KPI_Report'
        """
        logging.debug('Read release file')
        use_kpi_release = ReadSourceKPI(source_kpi, kpi_to_generate, kpi_type)
        use_kpi_release.parse_kpi()

        logging.debug('Parse file with counters')
        read_files_instance = FilesParser(path_dir, use_kpi_release.counters_need, generate_html_xlsx)
        read_files_instance.parse_files()

        logging.debug('Scan counters')
        scan_counters = ScanCounters(read_files_instance.measurements, use_kpi_release.use_kpi, use_kpi_release.counters_need,
                                     use_kpi_release.type_kpi)
        scan_counters.scan()

        logging.debug('Generate KPI Report')
        sheet_creator = SheetCreator(read_files_instance.path_dir, number_of_start_intervals_to_skip, number_of_end_intervals_to_skip,
                                     use_kpi_release.use_kpi, use_kpi_release.release_version, use_kpi_release.warnings, use_kpi_release.categories,
                                     read_files_instance.measurements, scan_counters.cells, scan_counters.kpi_exceptions, build, report_name)
        sheet_creator.generate_report()

        if generate_json:
            logging.debug('Generate JSON')
            generate_json = GenerateJSON(read_files_instance.path_dir, number_of_start_intervals_to_skip, number_of_end_intervals_to_skip,
                                         report_name)
            generate_json.generate_JSON()

        if generate_html_xlsx:
            logging.debug('Generate files xlsx and html with counters')
            generate_counters = GenerateFiles(read_files_instance.path_dir, read_files_instance.measurements, use_kpi_release.counters_name)
            generate_counters.generate()
